-- Skript Nr.4 Datentransfer prod_gl_artvorkommen --> wis-- Notwendigkeit Ausführung des Skripts prüfen! Das Skript dient dazu redundate Einträge im Datensatz-- prod_gl_arten.artvorkommen_gl_pt vom Datenimport ins WIS auszuschliessen. Sollte eigentlich nicht Notwendig sein.-- Stand 1. Oktober 2022-- Löschen von multiplen Fundmeldungen mit identischer Art, Fundadatum und KoordinateDELETE FROM prod_gl_arten.wis_artvorkommen as a USING prod_gl_arten.wis_artvorkommen as b WHERE a.lateinischer_name = b.lateinischer_name AND a.funddatum = b.funddatum AND st_equals(a.geometrie, b.geometrie) and a.id > b.id